import{c as l,Q as e,j as f,m as i}from"./chunks/framework.DOi4mjdC.js";const u="/assets/BufPool%E8%B5%84%E6%BA%90%E6%B1%A0%E5%88%92%E5%88%86.BGm0LFl5.png",s=JSON.parse('{"title":"TBufPool简介","description":"","frontmatter":{},"headers":[{"level":1,"title":"TBufPool简介","slug":"tbufpool简介"},{"level":2,"title":"功能图示","slug":"功能图示"},{"level":2,"title":"约束说明","slug":"约束说明"}],"relativePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBufPool/TBufPool简介.md","filePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBufPool/TBufPool简介.md"}'),t={name:"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBufPool/TBufPool简介.md"};function P(a,o,B,r,n,T){return e(),f("div",null,[...o[0]||(o[0]=[i('<h1 id="tbufpool简介" tabindex="-1">TBufPool简介 <a class="header-anchor" href="#tbufpool简介" aria-label="Permalink to &quot;TBufPool简介&quot;">​</a></h1><p>TPipe可以管理全局内存资源，而TBufPool可以手动管理或复用Unified Buffer/L1 Buffer物理内存，主要用于多个stage计算中Unified Buffer/L1 Buffer物理内存不足的场景。</p><h2 id="功能图示" tabindex="-1">功能图示 <a class="header-anchor" href="#功能图示" aria-label="Permalink to &quot;功能图示&quot;">​</a></h2><p>下图展示了资源池划分的过程：</p><ol><li>通过TPipe::<a href="./../TPipe/InitBuffer.html">InitBuffer</a>接口可以申请Buffer内存并使用队列进行管理；</li><li>通过TPipe::<a href="./../TPipe/InitBufPool.html">InitBufPool</a>可以划分出资源池BufPool1；</li><li>通过TPipe::<a href="./../TPipe/InitBufPool.html">InitBufPool</a>可以指定BufPool1与BufPool3地址和长度复用;</li><li>通过TBufPool::<a href="./InitBuffer-56.html">InitBuffer</a>及TBufPool::<a href="./InitBufPool-55.html">InitBufPool</a>接口继续将BufPool1及BufPool3划分成Buffer或TBufPool资源池。</li></ol><p><strong>图 1</strong> BufPool资源池划分<br><img src="'+u+'" alt="" title="BufPool资源池划分"></p><p>如图示的嵌套关系，最外层TBufPool(BufPool1与BufPool3)需要通过TPipe::InitBufPool申请并初始化，内层TBufPool(BufPool2)可以通过TBufPool::InitBufPool申请并初始化。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ol><li>TBufPool必须通过TPipe::InitBufPool或TBufPool::InitBufPool接口进行划分和初始化；资源池只能整体划分成部分，无法部分拼接为整体；</li><li>不同TBufPool资源池切换进行计算时，需要调用TBufPool::Reset()接口清空已完成计算的TBufPool，清空后的TBufPool资源池及分配的Buffer和数据默认无效；</li><li>不同资源池间分配的Buffer无法混用避免数据踩踏；</li><li>AllocTensor/FreeTensor、EnQue/DeQue在切分TBufPool资源池时必须成对匹配使用，自动确保同步；</li><li>切换资源池的时候，若手写同步，Ascend C不保证地址读写复用同步，因此不推荐手写同步。</li></ol>',9)])])}const h=l(t,[["render",P]]);export{s as __pageData,h as default};
